import { z } from "zod";
import type {
	JSONSchema,
	JSONSchemaProperty,
} from "@/components/ui/form-builder/types";
import { formSchemaToZod } from "@/lib/schema-converter";

const condition = z
	.object({
		field: z.string().min(1),
		operator: z.enum(["equals", "notEquals", "in", "isTruthy"]),
		value: z.unknown().optional(),
	})
	.refine(
		(rule) => rule.operator !== "in" || Array.isArray(rule.value),
		"The in operator needs an array",
	);
const property: z.ZodType<JSONSchemaProperty> = z.lazy(() =>
	z
		.object({
			type: z.enum([
				"string",
				"number",
				"integer",
				"boolean",
				"object",
				"array",
			]),
			showIf: condition.optional(),
			properties: z.record(z.string(), property).optional(),
			items: property.optional(),
			stepGroup: z.number().int().nonnegative().optional(),
		})
		.passthrough(),
) as z.ZodType<JSONSchemaProperty>;
const schemaPatch = z
	.object({
		type: z.literal("object"),
		properties: z.record(z.string(), property),
		required: z.array(z.string()).optional(),
		steps: z
			.array(
				z.object({
					id: z.string().min(1),
					title: z.string().min(1),
					showIf: condition.optional(),
				}),
			)
			.optional(),
		stepGroupMap: z
			.record(z.string(), z.number().int().nonnegative())
			.optional(),
	})
	.passthrough();

/** Merge an AI schema patch without discarding unrelated unsaved fields. */
export function applyAISchema(
	current: JSONSchema | undefined,
	input: unknown,
): JSONSchema {
	const args = z
		.object({ schema: z.string().min(2).max(200000) })
		.strict()
		.parse(input);
	const patch = schemaPatch.parse(JSON.parse(args.schema));
	const properties = {
		...current?.properties,
		...Object.fromEntries(
			Object.entries(patch.properties).map(([key, value]) => [
				key,
				{ ...current?.properties[key], ...value },
			]),
		),
	};
	const next = { ...current, ...patch, properties } as JSONSchema;
	const validate = (fields: Record<string, JSONSchemaProperty>) => {
		for (const [key, field] of Object.entries(fields)) {
			if (["__proto__", "prototype", "constructor"].includes(key))
				throw new Error("Invalid field name");
			if (field.showIf && !Object.hasOwn(fields, field.showIf.field))
				throw new Error("Visibility condition references an unknown field");
			if (field.properties) validate(field.properties);
			if (field.items?.properties) validate(field.items.properties);
		}
	};
	validate(properties);
	if (next.required?.some((key) => !Object.hasOwn(properties, key)))
		throw new Error("Required references an unknown field");
	if (
		next.steps?.some(
			(step) => step.showIf && !Object.hasOwn(properties, step.showIf.field),
		)
	)
		throw new Error("Step condition references an unknown field");
	if (
		new Set(next.steps?.map((step) => step.id)).size !==
		(next.steps?.length ?? 0)
	)
		throw new Error("Step IDs must be unique");
	const stepCount = Math.max(1, next.steps?.length ?? 0);
	if (
		Object.values(properties).some(
			({ stepGroup }) =>
				stepGroup !== undefined &&
				(!Number.isInteger(stepGroup) ||
					stepGroup < 0 ||
					stepGroup >= stepCount),
		)
	)
		throw new Error("Field references an unknown step");
	if (
		Object.entries(next.stepGroupMap ?? {}).some(
			([field, step]) =>
				!Object.hasOwn(properties, field) ||
				!Number.isInteger(step) ||
				step < 0 ||
				step >= stepCount,
		)
	)
		throw new Error("Step map references an unknown field or step");
	formSchemaToZod(next as unknown as Parameters<typeof formSchemaToZod>[0]);
	return next;
}

"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { useRegisterPageAIContext } from "@btst/stack/page-context";
import { applyAISchema } from "./ai-schema";
import {
	useNotify,
	PermissionAccess,
	usePluginOverrides,
	usePluginSiteNavigation,
	useTranslate,
} from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from "@/components/ui/select";
import { ArrowLeft, Save } from "lucide-react";
import { FormBuilder } from "@/components/ui/form-builder";
import type { JSONSchema } from "@/components/ui/form-builder/types";

import { useSuspenseFormForUpdate, useFormBuilderForm } from "@btst/plugin-form-builder/client/hooks";
import type { FormBuilderPluginOverrides } from "../../overrides";
import { slugify } from "../../../utils";
import type { SerializedForm } from "../../../types";
import { formBuilderPermissions } from "../../../permissions";
import { NotFoundPage } from "./404-page";
import { FORM_BUILDER_PLUGIN_ID } from "../../constants";

export interface FormBuilderPageProps {
	id?: string;
}

/**
 * Entry point component that conditionally renders the appropriate
 * sub-component based on whether we're creating or editing a form.
 * This avoids conditional hook calls which violate React's Rules of Hooks.
 */
export function FormBuilderPage({ id }: FormBuilderPageProps) {
	if (id) {
		return <EditFormBuilderPage id={id} />;
	}
	return <CreateFormBuilderPage />;
}

/**
 * Component for editing an existing form.
 * Uses the update-authorized editor query unconditionally since id is defined.
 */
function EditFormBuilderPage({ id }: { id: string }) {
	const { form: existingForm } = useSuspenseFormForUpdate(id);
	if (!existingForm) return <NotFoundPage />;
	return <FormBuilderPageContent id={id} existingForm={existingForm} />;
}

/**
 * Component for creating a new form.
 * No data fetching needed.
 */
function CreateFormBuilderPage() {
	return <FormBuilderPageContent />;
}

interface FormBuilderPageContentProps {
	id?: string;
	existingForm?: SerializedForm | null;
}

interface FormBuilderFormValues {
	name: string;
	slug: string;
	status: "active" | "inactive" | "archived";
	schema: string;
}

function FormBuilderPageContent({
	id,
	existingForm,
}: FormBuilderPageContentProps) {
	const t = useTranslate();
	const notify = useNotify();
	const { localization } = usePluginOverrides<FormBuilderPluginOverrides>(
		FORM_BUILDER_PLUGIN_ID,
	);
	const {
		Link: LinkComponent,
		navigate,
		resolve,
	} = usePluginSiteNavigation(FORM_BUILDER_PLUGIN_ID);

	// Form state
	const [name, setName] = useState(existingForm?.name || "");
	const [slug, setSlug] = useState(existingForm?.slug || "");
	const [status, setStatus] = useState<"active" | "inactive" | "archived">(
		existingForm?.status || "active",
	);
	const [schema, setSchema] = useState<JSONSchema | undefined>(() => {
		if (existingForm?.schema) {
			try {
				return JSON.parse(existingForm.schema) as JSONSchema;
			} catch {
				return undefined;
			}
		}
		return undefined;
	});

	// Auto-generate slug from name
	const [autoSlug, setAutoSlug] = useState(!id);
	const [schemaVersion, setSchemaVersion] = useState(0);
	const schemaRef = useRef(schema);
	schemaRef.current = schema;

	useEffect(() => {
		if (autoSlug && name) {
			setSlug(slugify(name));
		}
	}, [name, autoSlug]);

	const handleSchemaChange = useCallback((newSchema: JSONSchema) => {
		schemaRef.current = newSchema;
		setSchema(newSchema);
	}, []);

	// Core resource form: submits the right mutation, awaits invalidation,
	// notifies success/error via useNotify(), redirects after create, and
	// exposes server validation issues as fieldErrors for inline display.
	const resourceForm = useFormBuilderForm<FormBuilderFormValues>({
		action: id ? "edit" : "create",
		record: id ? (existingForm ?? null) : null,
		successMessage: (_result, action) =>
			action === "create"
				? (localization?.FORM_BUILDER_TOAST_CREATE_SUCCESS ??
					t("formBuilder.toasts.createSuccess", "Form created successfully"))
				: (localization?.FORM_BUILDER_TOAST_UPDATE_SUCCESS ??
					t("formBuilder.toasts.updateSuccess", "Form updated successfully")),
		errorMessage: (error) =>
			error.statusCode === 409
				? (localization?.FORM_BUILDER_TOAST_DUPLICATE_SLUG ??
					t(
						"formBuilder.toasts.duplicateSlug",
						"A form with this slug already exists",
					))
				: (localization?.FORM_BUILDER_TOAST_ERROR ??
					t(
						"formBuilder.toasts.error",
						"An error occurred. Please try again.",
					)),
		toCreateVars: (values) => values,
		toUpdateVars: (values) => ({
			id: id ?? "",
			data: {
				name: values.name,
				schema: values.schema,
				status: values.status,
			},
		}),
		onSuccess: (result) => {
			if (!id && result) return navigate("forms", result.id, "edit");
		},
	});

	const handleSave = async () => {
		if (!name.trim()) {
			notify.error(
				localization?.FORM_BUILDER_TOAST_NAME_REQUIRED ??
					t("formBuilder.toasts.nameRequired", "Name is required"),
			);
			return;
		}
		if (!slug.trim()) {
			notify.error(
				localization?.FORM_BUILDER_TOAST_SLUG_REQUIRED ??
					t("formBuilder.toasts.slugRequired", "Slug is required"),
			);
			return;
		}
		if (!schema) {
			notify.error(
				localization?.FORM_BUILDER_TOAST_SCHEMA_REQUIRED ??
					t(
						"formBuilder.toasts.schemaRequired",
						"Please add at least one field to the form",
					),
			);
			return;
		}

		// resourceForm.submit never throws: success notifies + redirects via
		// the config above; errors land on resourceForm.fieldErrors or notify.
		await resourceForm.submit({
			name,
			slug,
			status,
			schema: JSON.stringify(schema),
		});
	};

	const isSaving = resourceForm.isSubmitting;
	useRegisterPageAIContext({
		routeName: "form-builder-editor",
		pageDescription: JSON.stringify({
			page: "Visual form draft. Add/edit only requested fields, steps and showIf rules. Do not discard unmentioned fields. The user saves the form.",
			name,
			schema,
		}).slice(0, 16000),
		clientTools: {
			updateFormSchema: async (input: unknown) => {
				if (isSaving)
					return {
						success: false,
						message: "Wait for the form save to finish.",
					};
				try {
					const next = applyAISchema(schemaRef.current, input);
					schemaRef.current = next;
					setSchema(next);
					setSchemaVersion((value) => value + 1);
					return {
						success: true,
						message:
							"Form draft updated. Review its fields and conditions before saving.",
					};
				} catch {
					return {
						success: false,
						message: "Invalid form schema or visibility rules.",
					};
				}
			},
		},
	});
	const fieldError = (field: string): string | undefined => {
		const error = resourceForm.fieldErrors[field];
		if (!error) return undefined;
		return Array.isArray(error) ? error[0] : error;
	};
	const saveButton = (
		<div className="ml-auto">
			<Button onClick={handleSave} disabled={isSaving}>
				<Save className="mr-2 h-4 w-4" />
				{isSaving
					? (localization?.FORM_BUILDER_STATUS_SAVING ??
						t("formBuilder.common.statusSaving", "Saving..."))
					: id
						? (localization?.FORM_BUILDER_BUTTON_SAVE ??
							t("formBuilder.common.buttonSave", "Save"))
						: (localization?.FORM_BUILDER_BUTTON_CREATE ??
							t("formBuilder.common.buttonCreate", "Create"))}
			</Button>
		</div>
	);

	return (
		<div className="flex h-full flex-col" data-testid="form-builder-page">
			{/* Header */}
			<div className="flex items-center gap-4 border-b p-4">
				<Button variant="ghost" size="icon" asChild>
					<LinkComponent href={resolve("forms").href}>
						<ArrowLeft className="h-4 w-4" />
					</LinkComponent>
				</Button>

				<div className="flex flex-col gap-1">
					<Label htmlFor="form-name" className="text-xs text-muted-foreground">
						{localization?.FORM_BUILDER_LABEL_NAME ??
							t("formBuilder.common.labelName", "Name")}
					</Label>
					<Input
						id="form-name"
						value={name}
						onChange={(e) => setName(e.target.value)}
						placeholder={
							localization?.FORM_BUILDER_EDITOR_NAME_PLACEHOLDER ??
							t("formBuilder.editor.namePlaceholder", "Enter form name")
						}
						className="h-8 w-48"
					/>
					{fieldError("name") && (
						<p className="text-xs text-destructive">{fieldError("name")}</p>
					)}
				</div>

				<div className="flex flex-col gap-1">
					<Label htmlFor="form-slug" className="text-xs text-muted-foreground">
						{localization?.FORM_BUILDER_LABEL_SLUG ??
							t("formBuilder.common.labelSlug", "Slug")}
					</Label>
					<Input
						id="form-slug"
						value={slug}
						onChange={(e) => {
							setSlug(e.target.value);
							setAutoSlug(false);
						}}
						placeholder={
							localization?.FORM_BUILDER_EDITOR_SLUG_PLACEHOLDER ??
							t("formBuilder.editor.slugPlaceholder", "enter-form-slug")
						}
						className="h-8 w-48 font-mono text-sm"
						disabled={!!id}
					/>
					{fieldError("slug") && (
						<p className="text-xs text-destructive">{fieldError("slug")}</p>
					)}
				</div>

				<div className="flex flex-col gap-1">
					<Label
						htmlFor="form-status"
						className="text-xs text-muted-foreground"
					>
						{localization?.FORM_BUILDER_LABEL_STATUS ??
							t("formBuilder.common.labelStatus", "Status")}
					</Label>
					<Select
						value={status}
						onValueChange={(v) => setStatus(v as typeof status)}
					>
						<SelectTrigger className="h-8 w-28">
							<SelectValue />
						</SelectTrigger>
						<SelectContent>
							<SelectItem value="active">
								{localization?.FORM_BUILDER_STATUS_ACTIVE ??
									t("formBuilder.common.statusActive", "Active")}
							</SelectItem>
							<SelectItem value="inactive">
								{localization?.FORM_BUILDER_STATUS_INACTIVE ??
									t("formBuilder.common.statusInactive", "Inactive")}
							</SelectItem>
							<SelectItem value="archived">
								{localization?.FORM_BUILDER_STATUS_ARCHIVED ??
									t("formBuilder.common.statusArchived", "Archived")}
							</SelectItem>
						</SelectContent>
					</Select>
				</div>

				{id && existingForm ? (
					<PermissionAccess
						permission={formBuilderPermissions.form.update({
							formId: existingForm.id,
							...(existingForm.createdBy
								? { ownerId: existingForm.createdBy }
								: {}),
							status: existingForm.status,
						})}
					>
						{saveButton}
					</PermissionAccess>
				) : !id ? (
					<PermissionAccess permission={formBuilderPermissions.form.create()}>
						{saveButton}
					</PermissionAccess>
				) : null}
			</div>

			{/* Form Builder */}
			<FormBuilder
				key={schemaVersion}
				value={schema}
				onChange={handleSchemaChange}
				className="flex-1"
			/>
		</div>
	);
}

"use client";

import { lazy } from "react";
import { usePluginOverrides } from "@btst/stack/context";
import type { FormBuilderPluginOverrides } from "../../overrides";
import {
	ComposedRoute,
	PermissionRouteAccess,
} from "@btst/stack/client/components";
import { DefaultError } from "../shared/default-error";
import { FormBuilderSkeleton } from "../loading/form-builder-skeleton";
import { NotFoundPage } from "./404-page";
import { formBuilderPermissions } from "../../../permissions";
import { FORM_BUILDER_PLUGIN_ID } from "../../constants";
import { useSuspenseFormForUpdate } from "@btst/plugin-form-builder/client/hooks";

const FormBuilderPage = lazy(() =>
	import("./form-builder-page.internal").then((m) => ({
		default: m.FormBuilderPage,
	})),
);

export interface FormBuilderPageProps {
	id?: string;
}

export function FormBuilderPageComponent({ id }: FormBuilderPageProps) {
	const { onRouteError } = usePluginOverrides<FormBuilderPluginOverrides>(
		FORM_BUILDER_PLUGIN_ID,
	);

	const isNew = !id;
	const path = isNew ? "/forms/new" : `/forms/${id}/edit`;

	return (
		<ComposedRoute
			path={path}
			PageComponent={AuthorizedFormBuilderPage}
			ErrorComponent={DefaultError}
			LoadingComponent={FormBuilderSkeleton}
			NotFoundComponent={NotFoundPage}
			props={{ id }}
			onError={(error) => {
				if (onRouteError) {
					onRouteError("formBuilder", error, {
						path,
						params: id ? { id } : {},
						isSSR: typeof window === "undefined",
					});
				}
			}}
		/>
	);
}

function AuthorizedFormBuilderPage({ id }: FormBuilderPageProps) {
	if (!id) {
		return (
			<PermissionRouteAccess
				permission={formBuilderPermissions.form.create()}
				LoadingComponent={FormBuilderSkeleton}
			>
				<FormBuilderPage />
			</PermissionRouteAccess>
		);
	}
	return <AuthorizedExistingFormBuilderPage id={id} />;
}

function AuthorizedExistingFormBuilderPage({ id }: { id: string }) {
	const { form } = useSuspenseFormForUpdate(id);
	if (!form) return <NotFoundPage />;
	return (
		<PermissionRouteAccess
			permission={formBuilderPermissions.form.update({
				formId: form.id,
				...(form.createdBy ? { ownerId: form.createdBy } : {}),
				status: form.status,
			})}
			LoadingComponent={FormBuilderSkeleton}
		>
			<FormBuilderPage id={id} />
		</PermissionRouteAccess>
	);
}

"use client";

import { useEffect, useRef, useState } from "react";
import {
	useNotify,
	PermissionAccess,
	usePluginOverrides,
	usePluginSiteNavigation,
	useTranslate,
} from "@btst/stack/context";
import { useListState, type ListStateSchema } from "@btst/stack/client/hooks";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
	Table,
	TableBody,
	TableCell,
	TableHead,
	TableHeader,
	TableRow,
} from "@/components/ui/table";
import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuItem,
	DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
	AlertDialog,
	AlertDialogAction,
	AlertDialogCancel,
	AlertDialogContent,
	AlertDialogDescription,
	AlertDialogFooter,
	AlertDialogHeader,
	AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
	MoreHorizontal,
	Plus,
	Pencil,
	Trash2,
	FileText,
	Loader2,
	Search,
} from "lucide-react";

import { useForms, useSuspenseForms, useDeleteForm } from "@btst/plugin-form-builder/client/hooks";
import type { FormBuilderPluginOverrides } from "../../overrides";
import { PageWrapper } from "../shared/page-wrapper";
import { EmptyState } from "../shared/empty-state";
import { Pagination } from "../shared/pagination";
import { formBuilderPermissions } from "../../../permissions";
import { FORM_BUILDER_PLUGIN_ID } from "../../constants";
import { cn } from "../../../utils";

// URL-synced search state: `?q=...` while typing (history: replace), clean
// URL when the query is empty (the default is omitted from the URL).
const LIST_STATE_SCHEMA = {
	q: { type: "string", default: "", history: "replace" },
} as const satisfies ListStateSchema;

const SEARCH_DEBOUNCE_MS = 300;

export function FormListPage() {
	const t = useTranslate();
	const notify = useNotify();
	const { localization, classNames } =
		usePluginOverrides<FormBuilderPluginOverrides>(FORM_BUILDER_PLUGIN_ID);
	const { Link, navigate, resolve } = usePluginSiteNavigation(
		FORM_BUILDER_PLUGIN_ID,
	);

	const [{ q: search }, setListState] = useListState(
		"form-builder-forms",
		LIST_STATE_SCHEMA,
	);

	// Local input state debounced into the URL-synced query, so the list
	// query (and URL) only update after the user pauses typing.
	const [searchInput, setSearchInput] = useState(search);

	// External `q` changes (hydration after SSR-empty search params,
	// back/forward navigation) re-seed the input instead of being clobbered
	// by the debounced write below, which only reflects user edits.
	const lastSyncedSearch = useRef(search);
	useEffect(() => {
		if (search !== lastSyncedSearch.current) {
			lastSyncedSearch.current = search;
			setSearchInput(search);
		}
	}, [search]);

	useEffect(() => {
		if (searchInput === search) return;
		const timeout = setTimeout(() => {
			lastSyncedSearch.current = searchInput;
			setListState({ q: searchInput });
		}, SEARCH_DEBOUNCE_MS);
		return () => clearTimeout(timeout);
	}, [searchInput, search, setListState]);

	const hasSearch = search.trim().length > 0;

	// The default (unsearched) list stays on the suspense hook so SSR/SSG
	// hydration works; the searched list uses the non-suspense hook so
	// typing shows an inline loading state instead of suspending the page.
	const defaultList = useSuspenseForms();
	const searchedList = useForms({ search, enabled: hasSearch });

	const activeList = hasSearch ? searchedList : defaultList;
	const { forms, total, hasMore, isLoadingMore, loadMore } = activeList;
	const isSearchLoading = hasSearch && searchedList.isLoading;

	const deleteMutation = useDeleteForm();

	const [deleteId, setDeleteId] = useState<string | null>(null);

	const LinkComponent = Link || "a";

	const handleDelete = async () => {
		if (!deleteId) return;

		try {
			await deleteMutation.mutateAsync(deleteId);
		} catch {
			notify.error(
				localization?.FORM_BUILDER_TOAST_ERROR ??
					t("formBuilder.toasts.error", "An error occurred. Please try again."),
			);
			return;
		}
		notify.success(
			localization?.FORM_BUILDER_TOAST_DELETE_SUCCESS ??
				t("formBuilder.toasts.deleteSuccess", "Form deleted successfully"),
		);
		setDeleteId(null);
	};

	const getStatusBadge = (status: string) => {
		const colors: Record<string, string> = {
			active:
				"bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200",
			inactive:
				"bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200",
			archived: "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-200",
		};
		return (
			<span
				className={`px-2 py-1 rounded-full text-xs font-medium ${colors[status] || colors.inactive}`}
			>
				{status}
			</span>
		);
	};

	const newFormButton = (
		<PermissionAccess permission={formBuilderPermissions.form.create()}>
			<Button asChild>
				<LinkComponent href={resolve("forms", "new").href}>
					<Plus className="mr-2 h-4 w-4" />
					{localization?.FORM_BUILDER_BUTTON_NEW_FORM ??
						t("formBuilder.common.buttonNewForm", "New Form")}
				</LinkComponent>
			</Button>
		</PermissionAccess>
	);

	return (
		<PageWrapper testId="form-list-page">
			<div className="w-full max-w-5xl space-y-6">
				<div className="flex items-center justify-between">
					<div>
						<h1 className="text-2xl font-bold">
							{localization?.FORM_BUILDER_LIST_TITLE ??
								t("formBuilder.list.title", "Forms")}
						</h1>
						<p className="text-muted-foreground">
							{localization?.FORM_BUILDER_LIST_SUBTITLE ??
								t("formBuilder.list.subtitle", "Manage your forms")}
						</p>
					</div>
					{newFormButton}
				</div>

				<div className="relative max-w-sm">
					<Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
					<Input
						data-testid="form-builder-list-search"
						value={searchInput}
						onChange={(e) => setSearchInput(e.target.value)}
						placeholder={
							localization?.FORM_BUILDER_LIST_SEARCH_PLACEHOLDER ??
							t("formBuilder.list.searchPlaceholder", "Search forms...")
						}
						className="pl-9"
					/>
					{isSearchLoading && (
						<Loader2 className="absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 animate-spin text-muted-foreground" />
					)}
				</div>

				{forms.length === 0 ? (
					isSearchLoading ? null : hasSearch ? (
						<EmptyState
							title={
								localization?.FORM_BUILDER_LIST_SEARCH_EMPTY ??
								t("formBuilder.list.searchEmpty", "No forms match your search")
							}
							description={
								localization?.FORM_BUILDER_LIST_SEARCH_EMPTY_DESCRIPTION ??
								t(
									"formBuilder.list.searchEmptyDescription",
									"Try a different search term.",
								)
							}
						/>
					) : (
						<EmptyState
							title={
								localization?.FORM_BUILDER_LIST_EMPTY ??
								t("formBuilder.list.empty", "No forms yet")
							}
							description={
								localization?.FORM_BUILDER_LIST_EMPTY_DESCRIPTION ??
								t(
									"formBuilder.list.emptyDescription",
									"Create your first form to get started.",
								)
							}
							action={newFormButton}
						/>
					)
				) : (
					<>
						<div
							className={cn("rounded-lg border", classNames?.table)}
							data-testid="form-builder-list-table"
						>
							<Table>
								<TableHeader>
									<TableRow>
										<TableHead>
											{localization?.FORM_BUILDER_LIST_COLUMN_NAME ??
												t("formBuilder.list.columnName", "Name")}
										</TableHead>
										<TableHead>
											{localization?.FORM_BUILDER_LIST_COLUMN_SLUG ??
												t("formBuilder.list.columnSlug", "Slug")}
										</TableHead>
										<TableHead>
											{localization?.FORM_BUILDER_LIST_COLUMN_STATUS ??
												t("formBuilder.list.columnStatus", "Status")}
										</TableHead>
										<TableHead>
											{localization?.FORM_BUILDER_LIST_COLUMN_CREATED ??
												t("formBuilder.list.columnCreated", "Created")}
										</TableHead>
										<TableHead className="w-12">
											{localization?.FORM_BUILDER_LIST_COLUMN_ACTIONS ??
												t("formBuilder.list.columnActions", "Actions")}
										</TableHead>
									</TableRow>
								</TableHeader>
								<TableBody>
									{forms.map((form) => (
										<TableRow key={form.id} className={classNames?.tableRow}>
											<TableCell className="font-medium">{form.name}</TableCell>
											<TableCell className="text-muted-foreground font-mono text-sm">
												{form.slug}
											</TableCell>
											<TableCell>{getStatusBadge(form.status)}</TableCell>
											<TableCell className="text-muted-foreground">
												{new Date(form.createdAt).toLocaleDateString()}
											</TableCell>
											<TableCell>
												<DropdownMenu>
													<DropdownMenuTrigger asChild>
														<Button variant="ghost" size="icon">
															<MoreHorizontal className="h-4 w-4" />
															<span className="sr-only">
																{localization?.FORM_BUILDER_LIST_COLUMN_ACTIONS ??
																	t(
																		"formBuilder.list.columnActions",
																		"Actions",
																	)}
															</span>
														</Button>
													</DropdownMenuTrigger>
													<DropdownMenuContent align="end">
														<PermissionAccess
															permission={formBuilderPermissions.form.update({
																formId: form.id,
																...(form.createdBy
																	? { ownerId: form.createdBy }
																	: {}),
																status: form.status,
															})}
														>
															<DropdownMenuItem
																onClick={() =>
																	navigate("forms", form.id, "edit")
																}
															>
																<Pencil className="mr-2 h-4 w-4" />
																{localization?.FORM_BUILDER_LIST_ACTION_EDIT ??
																	t("formBuilder.list.actionEdit", "Edit")}
															</DropdownMenuItem>
														</PermissionAccess>
														<PermissionAccess
															permission={formBuilderPermissions.submission.read(
																{
																	scope: "collection",
																	formId: form.id,
																	formExists: true,
																	...(form.createdBy
																		? { ownerId: form.createdBy }
																		: {}),
																},
															)}
														>
															<DropdownMenuItem
																onClick={() =>
																	navigate("forms", form.id, "submissions")
																}
															>
																<FileText className="mr-2 h-4 w-4" />
																{localization?.FORM_BUILDER_LIST_ACTION_SUBMISSIONS ??
																	t(
																		"formBuilder.list.actionSubmissions",
																		"Submissions",
																	)}
															</DropdownMenuItem>
														</PermissionAccess>
														<PermissionAccess
															permission={formBuilderPermissions.form.delete({
																formId: form.id,
																...(form.createdBy
																	? { ownerId: form.createdBy }
																	: {}),
																status: form.status,
															})}
														>
															<DropdownMenuItem
																className="text-destructive"
																onClick={() => setDeleteId(form.id)}
															>
																<Trash2 className="mr-2 h-4 w-4" />
																{localization?.FORM_BUILDER_LIST_ACTION_DELETE ??
																	t("formBuilder.list.actionDelete", "Delete")}
															</DropdownMenuItem>
														</PermissionAccess>
													</DropdownMenuContent>
												</DropdownMenu>
											</TableCell>
										</TableRow>
									))}
								</TableBody>
							</Table>
						</div>

						<Pagination
							total={total}
							showing={forms.length}
							hasMore={hasMore}
							isLoadingMore={isLoadingMore}
							onLoadMore={loadMore}
							className={classNames?.pagination}
							labels={{
								showing:
									localization?.FORM_BUILDER_LIST_PAGINATION_SHOWING ??
									t(
										"formBuilder.list.paginationShowing",
										"Showing {count} of {total}",
									),
								next:
									localization?.FORM_BUILDER_LIST_PAGINATION_NEXT ??
									t("formBuilder.list.paginationNext", "Load More"),
								loading:
									localization?.FORM_BUILDER_STATUS_LOADING ??
									t("formBuilder.common.statusLoading", "Loading..."),
							}}
						/>
					</>
				)}
			</div>

			{/* Delete confirmation dialog */}
			<AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
				<AlertDialogContent>
					<AlertDialogHeader>
						<AlertDialogTitle>
							{localization?.FORM_BUILDER_LIST_DELETE_TITLE ??
								t("formBuilder.list.deleteTitle", "Delete Form")}
						</AlertDialogTitle>
						<AlertDialogDescription>
							{localization?.FORM_BUILDER_EDITOR_DELETE_CONFIRM ??
								t(
									"formBuilder.editor.deleteConfirm",
									"Are you sure you want to delete this form? All submissions will also be deleted.",
								)}
						</AlertDialogDescription>
					</AlertDialogHeader>
					<AlertDialogFooter>
						<AlertDialogCancel>
							{localization?.FORM_BUILDER_BUTTON_CANCEL ??
								t("formBuilder.common.buttonCancel", "Cancel")}
						</AlertDialogCancel>
						<AlertDialogAction
							onClick={handleDelete}
							className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
						>
							{deleteMutation.isPending
								? (localization?.FORM_BUILDER_STATUS_DELETING ??
									t("formBuilder.common.statusDeleting", "Deleting..."))
								: (localization?.FORM_BUILDER_BUTTON_DELETE ??
									t("formBuilder.common.buttonDelete", "Delete"))}
						</AlertDialogAction>
					</AlertDialogFooter>
				</AlertDialogContent>
			</AlertDialog>
		</PageWrapper>
	);
}

